<?php
declare(strict_types=1);
namespace HardnessMcp\Tools\Finance;
use HardnessMcp\Tools\ToolDefinition;
final class FinanceSummaryDefinition { public static function forKind(string $kind): ToolDefinition { $receivable=$kind==='receivable'; return new ToolDefinition($receivable?'hardness.finance.receivables_summary':'hardness.finance.payables_summary',$receivable?'Returns a management summary of accounts receivable by due date (default) or receipt date. Use date_basis settlement_date with status settled to report receipts in the period.':'Returns a management summary of accounts payable by due date (default) or payment date. Use date_basis settlement_date with status settled to report payments in the period.',['type'=>'object','properties'=>['date_from'=>['type'=>'string','minLength'=>10,'maxLength'=>10],'date_to'=>['type'=>'string','minLength'=>10,'maxLength'=>10],'date_basis'=>['type'=>'string','enum'=>['due_date','settlement_date']],'view'=>['type'=>'string','enum'=>['summary','titles']],'cursor'=>['type'=>'string','minLength'=>4,'maxLength'=>100],'group_by'=>['type'=>'string','enum'=>['day','month','partner','carrier','origin','status']],'status'=>['type'=>'string','enum'=>['all','open','settled','overdue']],'partner_id'=>['type'=>'integer','minimum'=>1],'carrier_id'=>['type'=>'integer','minimum'=>1],'limit'=>['type'=>'integer','minimum'=>1,'maximum'=>50]],'required'=>['date_from','date_to','group_by'],'additionalProperties'=>false],[$receivable?'finance:receivables:read':'finance:payables:read']); } }
